package sh.pcx.packmerger.discovery;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Describes how to locate the resource pack <em>generated by another installed
 * plugin</em> (Oraxen, Nexo, ItemsAdder, ModelEngine, …) so PackMerger can pull
 * it into the merge automatically.
 *
 * <p>Adapters are data-driven. Each one has:</p>
 * <ul>
 *   <li>an {@link #alias()}: the staged filename ({@code packs/.plugin-packs/<alias>.zip})
 *       and the name used in {@code priority:};</li>
 *   <li>a {@link #pluginName()} used for presence detection ({@code null} means "no
 *       gate": the source is used whenever it exists, which is how operator-defined
 *       adapters without a {@code plugin:} key behave);</li>
 *   <li>one or more {@link Source sources}. Each source is an ordered list of
 *       {@link Candidate candidate paths} (relative to {@code plugins/}, or absolute);
 *       the first candidate that exists wins. When an adapter has several sources
 *       (FreeMinecraftModels ships a generated zip <em>and</em> a folder of extra
 *       packs) every resolved source is unioned into the one staged pack, earlier
 *       sources first;</li>
 *   <li>or, for plugins that only publish their pack as a download, a {@link #url()}.
 *       Those are fetched only while the plugin is installed.</li>
 * </ul>
 *
 * <p>A candidate is either a single pack (a {@code .zip}, or a directory with
 * {@code pack.mcmeta} or {@code assets/} at its root) or a <em>cluster</em>: a
 * directory whose children are packs (folders or zips). A cluster is unioned into
 * one staged pack. Directories that are not packs themselves but contain packs are
 * treated as clusters automatically.</p>
 *
 * <p>Output paths differ between plugin versions and can change, so every
 * adapter's paths are overridable via {@code plugin-packs.sources.<alias>.path}
 * in config, and operators can declare new adapters there without a release.</p>
 */
public final class PluginPackAdapter {

    /** One candidate location for a plugin's pack. */
    public record Candidate(String path, boolean cluster) {}

    /** An ordered list of candidates; the first one that exists is used. */
    public record Source(List<Candidate> candidates) {
        public Source {
            candidates = List.copyOf(candidates);
        }

        /** A source whose candidates are single packs (zip or pack folder). */
        public static Source pack(String... paths) {
            List<Candidate> c = new ArrayList<>();
            for (String p : paths) c.add(new Candidate(p, false));
            return new Source(c);
        }

        /** A source whose candidates are clusters (folders of packs). */
        public static Source cluster(String... paths) {
            List<Candidate> c = new ArrayList<>();
            for (String p : paths) c.add(new Candidate(p, true));
            return new Source(c);
        }

        /** Appends {@code other}'s candidates as lower-priority fallbacks. */
        public Source then(Source other) {
            List<Candidate> c = new ArrayList<>(candidates);
            c.addAll(other.candidates);
            return new Source(c);
        }
    }

    /** A source that exists on disk, with whether it should be read as a cluster. */
    public record ResolvedSource(File file, boolean cluster) {}

    private final String alias;
    private final String pluginName;
    private final List<Source> sources;
    private final String url;

    public PluginPackAdapter(String alias, String pluginName, List<Source> sources, String url) {
        this.alias = alias.toLowerCase(Locale.ROOT);
        this.pluginName = pluginName == null || pluginName.isBlank() ? null : pluginName;
        this.sources = List.copyOf(sources);
        this.url = url == null || url.isBlank() ? null : url;
    }

    /** Convenience constructor for a local adapter with one or more sources. */
    public static PluginPackAdapter local(String alias, String pluginName, Source... sources) {
        return new PluginPackAdapter(alias, pluginName, List.of(sources), null);
    }

    /** Convenience constructor for a plugin that only publishes its pack as a download. */
    public static PluginPackAdapter remote(String alias, String pluginName, String url) {
        return new PluginPackAdapter(alias, pluginName, List.of(), url);
    }

    /** Staging filename and the name used to reference this pack in {@code priority:}. */
    public String alias() { return alias; }

    /** Bukkit plugin name used for presence detection, or {@code null} for "always active". */
    public String pluginName() { return pluginName; }

    /** Local sources, in priority order. Empty for URL adapters. */
    public List<Source> sources() { return sources; }

    /** Download URL for URL-sourced adapters, or {@code null}. */
    public String url() { return url; }

    /** @return {@code true} if this adapter is fetched from {@link #url()} rather than read from disk */
    public boolean isRemote() { return url != null; }

    /** Every candidate path across all sources (for messages and tests). */
    public List<String> candidatePaths() {
        List<String> out = new ArrayList<>();
        for (Source s : sources) for (Candidate c : s.candidates()) out.add(c.path());
        return out;
    }

    /**
     * Resolves every source that currently exists.
     *
     * @param pluginsFolder the server's {@code plugins/} directory
     * @return one entry per source whose candidate exists, in source order; empty
     *         when nothing was found
     */
    public List<ResolvedSource> resolve(File pluginsFolder) {
        List<ResolvedSource> out = new ArrayList<>();
        for (Source s : sources) {
            for (Candidate c : s.candidates()) {
                File f = resolvePath(pluginsFolder, c.path());
                if (f.exists()) {
                    out.add(new ResolvedSource(f, c.cluster()));
                    break;
                }
            }
        }
        return out;
    }

    /**
     * Resolves this plugin's primary generated-pack source (kept for callers that
     * only need "is there anything").
     *
     * @param pluginsFolder the server's {@code plugins/} directory
     * @param overridePath  an operator-supplied path (absolute, or relative to
     *                      {@code plugins/}); {@code null}/blank to use defaults
     * @return the first existing source, or {@code null} if nothing was found
     */
    public File resolveSource(File pluginsFolder, String overridePath) {
        if (overridePath != null && !overridePath.isBlank()) {
            File f = resolvePath(pluginsFolder, overridePath);
            return f.exists() ? f : null;
        }
        List<ResolvedSource> r = resolve(pluginsFolder);
        return r.isEmpty() ? null : r.get(0).file();
    }

    /** Absolute paths are used verbatim; relative ones resolve against {@code plugins/}. */
    static File resolvePath(File pluginsFolder, String path) {
        File f = new File(path);
        return f.isAbsolute() ? f : new File(pluginsFolder, path);
    }

    /**
     * Applies an operator override from {@code plugin-packs.sources.<alias>}.
     *
     * <ul>
     *   <li>{@code plugin} replaces the presence gate;</li>
     *   <li>{@code path} (one path or a list) replaces every built-in source with a
     *       single source made of those candidates; {@code cluster} sets how they are
     *       read (default: the built-in's first candidate's mode, else auto);</li>
     *   <li>{@code url} replaces the download URL of a URL adapter.</li>
     * </ul>
     */
    public PluginPackAdapter withOverride(PluginPackOverride o) {
        if (o == null) return this;
        String plugin = o.plugin() != null ? o.plugin() : pluginName;
        List<Source> newSources = sources;
        String newUrl = url;
        if (!o.paths().isEmpty()) {
            boolean defaultCluster = !sources.isEmpty()
                    && !sources.get(0).candidates().isEmpty()
                    && sources.get(0).candidates().get(0).cluster();
            boolean cluster = o.cluster() != null ? o.cluster() : defaultCluster;
            List<Candidate> c = new ArrayList<>();
            for (String p : o.paths()) c.add(new Candidate(p, cluster));
            newSources = List.of(new Source(c));
            newUrl = null; // an explicit local path wins over a download
        } else if (o.cluster() != null && !sources.isEmpty()) {
            List<Source> re = new ArrayList<>();
            for (Source s : sources) {
                List<Candidate> c = new ArrayList<>();
                for (Candidate cand : s.candidates()) c.add(new Candidate(cand.path(), o.cluster()));
                re.add(new Source(c));
            }
            newSources = re;
        }
        if (o.url() != null) {
            newUrl = o.url();
            if (o.paths().isEmpty()) newSources = List.of();
        }
        return new PluginPackAdapter(alias, plugin, newSources, newUrl);
    }

    /**
     * Builds an operator-defined adapter for an alias that has no built-in.
     *
     * @return the adapter, or {@code null} when the override declares neither a
     *         path nor a url (nothing to read)
     */
    public static PluginPackAdapter custom(String alias, PluginPackOverride o) {
        if (o == null || (o.paths().isEmpty() && o.url() == null)) return null;
        return new PluginPackAdapter(alias, o.plugin(), List.of(), null).withOverride(o);
    }

    /**
     * Operator-supplied settings for one adapter alias
     * ({@code plugin-packs.sources.<alias>}). Every field but {@code enabled} is
     * optional ({@code null}/empty = keep the built-in value).
     *
     * @param enabled whether the adapter is staged at all
     * @param plugin  Bukkit plugin name that must be installed, or {@code null}
     * @param paths   candidate paths (relative to {@code plugins/}, or absolute)
     * @param cluster whether the paths are clusters; {@code null} = built-in/auto
     * @param url     download URL; {@code null} = built-in
     */
    public record PluginPackOverride(boolean enabled, String plugin, List<String> paths,
                                     Boolean cluster, String url) {
        public PluginPackOverride {
            paths = paths == null ? List.of() : List.copyOf(paths);
            if (plugin != null && plugin.isBlank()) plugin = null;
            if (url != null && url.isBlank()) url = null;
        }
    }

    /**
     * The built-in adapter registry. Paths are best-effort defaults taken from each
     * plugin's documented output; operators override per alias in config when a
     * plugin's layout differs.
     */
    public static List<PluginPackAdapter> builtIns() {
        return List.of(
                local("oraxen", "Oraxen", Source.pack("Oraxen/pack/pack.zip")),
                local("nexo", "Nexo", Source.pack("Nexo/pack/pack.zip")),
                local("itemsadder", "ItemsAdder", Source.pack("ItemsAdder/output/generated.zip")),
                local("modelengine", "ModelEngine",
                        Source.pack("ModelEngine/resource pack.zip", "ModelEngine/resource pack")),
                // EliteMobs writes a folder of packs; the old single-pack paths stay as
                // fallbacks for older EliteMobs versions.
                local("elitemobs", "EliteMobs",
                        Source.cluster("EliteMobs/resource_pack")
                                .then(Source.pack("EliteMobs/resourcepack.zip", "EliteMobs/resourcepackv2"))),
                // FreeMinecraftModels: the generated zip plus a folder of extra packs.
                local("freeminecraftmodels", "FreeMinecraftModels",
                        Source.pack("FreeMinecraftModels/output/FreeMinecraftModels.zip",
                                "FreeMinecraftModels/resourcepack.zip"),
                        Source.cluster("FreeMinecraftModels/resource_pack")),
                local("nova", "Nova", Source.pack("Nova/resource_pack/ResourcePack.zip")),
                local("betterhud", "BetterHUD", Source.pack("BetterHUD/build.zip")),
                local("valhallammo", "ValhallaMMO", Source.pack("ValhallaMMO/resourcepack")),
                // vane writes its zip next to plugins/ in some versions and inside it in others.
                local("vane", "vane-core",
                        Source.pack("vane-resource-pack.zip", "../vane-resource-pack.zip")),
                local("backpackplus", "BackpackPlus", Source.pack("BackpackPlus/pack/resourcepack.zip")),
                local("betterstructures", "BetterStructures", Source.cluster("BetterStructures/resource_pack")),
                local("cannonrtp", "CannonRTP", Source.cluster("CannonRTP/resource_pack")),
                local("eternaltd", "EternalTD", Source.cluster("EternalTD/resource_pack")),
                local("infinitevehicles", "InfiniteVehicles",
                        Source.pack("InfiniteVehicles/InfiniteModelPack.zip")),
                local("megablocksurvivors", "MegaBlockSurvivors",
                        Source.pack("MegaBlockSurvivors/resourcepack", "MegaBlockSurvivors/resource_pack")),
                local("resurrectionchest", "ResurrectionChest", Source.cluster("ResurrectionChest/resource_pack")),
                // These two plugins publish their pack only as a download. Fetched only
                // while the plugin is installed (see config.yml for the disclosure).
                remote("mmoinventory", "MMOInventory",
                        "https://www.dropbox.com/s/1lftxmzh0q4b5yu/mmoinv_rp_3.zip?dl=1"),
                remote("realisticsurvival", "RealisticSurvival",
                        "https://www.dropbox.com/scl/fi/5ggc7t20bfxmrzsbb1kok/Realistic-Survival-RP-1.2.8-RELEASE.zip"
                                + "?rlkey=55llpn4zj146usfmm8okf1ier&dl=1")
        );
    }
}
